---取得关卡宝箱预览数据
function MazeMgr:GetQuestRewardBox(floor)
    --if isNull(self.rewardsBoxData) then
    local difficultyVo = CfUtils.GetCfVo(AutoIds.IdSetting366, "PatrolDifficultyCoefficientVo", self.mazeDifficultyId)
    local questRewardId = difficultyVo.bossRewardId
    if questRewardId == -1 then
        local floorId = checkNumber(self.mazeDifficultyId..floor)
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting367, "PatrolFloorRewardsVo", floorId)
        questRewardId = vo.rewardId
    end
    local rewardVo = CfUtils.GetCfVo(AutoIds.IdSetting752, "QuestRewardVo", questRewardId)
    local rewardsBoxData = parse_rewards(rewardVo.regularReward, rewardVo.regularRewardNum)
    --end
    return rewardsBoxData
end

