---MovePoint 去一个点（）
---@param point MazeMapPointDojo
function MazeMgr:MovePoint(point, cb, isInitPlayer)
    if not point then
        return 
    end

    --如果是同一个点直接激活当前点事件, 
    if not isInitPlayer and MazeMapMgr:GetInstance():IsCurPoint(point) then
        self:ActiveEvent()
        return
    end

    if self.isMoving then 
        return 
    end
    self.isMoving = true
    self.moveCor = cs_coroutine.start(self.DoMoveCor, self, point, cb, isInitPlayer)
end

function MazeMgr:DoMoveCor(point, cb, isInitPlayer)
    Events.Broadcast(Constants.EventNames.MazeClosePreview)
    coroutine.yield(cs_coroutine.start(MazePlayerMgr:GetInstance().MovePlayer, MazePlayerMgr:GetInstance(), point, isInitPlayer))
    --不是初始化角色
    if not isInitPlayer then
        coroutine.yield(WaitForSeconds(MazePlayerMgr:GetInstance().moveTime + MazePlayerMgr:GetInstance().prepareTime))
    else
        --起点的时候 初始化角色enter动作
        if MazeMapMgr:GetInstance():IsFirstPoint(point) then
            coroutine.yield(WaitForSeconds(MazePlayerMgr:GetInstance().enterTime))
        end
        Events.Broadcast(Constants.EventNames.MazeUIAllActive, {isTrue = true})
    end
    MazeMapMgr:GetInstance():SetCurPoint(point)

    if cb then
        cb()
    end
    Events.Broadcast(Constants.EventNames.MazeMoveEnd)
    self.isMoving = false
end

