--初始化历史足迹，返回当前点
function MazeMgr:InitFootInfo()
    if not self.foot then
        return nil
    end

    local line = 0
    local row = 0
    for k, v in pairs(self.foot) do
        if checkNumber(k) > line then
            if v.type == Constants.MazePointPassType.GetTo or v.type == Constants.MazePointPassType.Pass or v.type == Constants.MazePointPassType.RunAway then
                line = checkNumber(k)
                row = checkNumber(v.position)
            end
        end

        local point = MazeMapMgr:GetInstance():GetPoint(k, v.position)
        if point then
            point:SetPasssType(v.type)
        end
    end
    local points = MazeMapMgr:GetInstance().map

    local points = MazeMapMgr:GetInstance():GetPointsByLine(line)
    if points then
        local curPoint = points[row]
        if self.relicOptions and #self.relicOptions > 0 then
            curPoint.isNeedSelectRelic = 1
        end
        return curPoint
    end
    return nil
end

--获取关卡的战斗力
function MazeMgr:GetQuestEnumsPower(point)
    if not point then
        return 0
    end
    return checkNumber(point.difficultyFix) * self.monsterCombat
end

