--[[
    @desc: 获取怪物的血量能量信息
    author:{author}
    time:2020-07-24 14:52:16
    --@monstId: 怪物id
    @return:
]]
function MazeMgr:GetMonstHpEnergyInfo(monstId, monsterGrades)
    monstId = checkNumber(monstId)
    local t = {
        hpPercent = 1,
        id = monstId,
        energy = 0,
        grade = checkNumber(monsterGrades),
    }
    if self.monstInfos then
        local info = self.monstInfos[monstId] 
        if info then
            t.hpPercent = info.hpPercent
            t.energy = info.energy
        end
    end
    return t
end

function MazeMgr:GetAssistantInfo(key)
    key = checkString(key)
    local assistantIds = self.currentInfo[key].assists
    local data = {}
    for k, v in pairs(assistantIds) do
        local assistantData = CfUtils.GetCfVo(AutoIds.IdSetting361, "MazeAssistRoleVo", v.id)
        local cardData = CardConfMgr:GetCardByRefId(assistantData.cardId)
        local t = {
            hpPercent = 1,
            id = v.id,
            cardLevel = v.cardLevel,
            awakeningLevel = v.awakeningLevel,
            star = v.star,
            cardId = assistantData.cardId,
            defaultSkin = assistantData.cardSkin,
            energy = 0,
            rare = cardData.rare
        }
        table.insert(data, t)
    end
    return data
end

function MazeMgr:ReleaseMaze()
    local pages = UIModule.Instance.uiPages
    if pages.Count > 2 then
        UIModule.RemoveRecordToCustomDialog(Constants.UITypeIds.BattleSelection)
    end
end

function MazeMgr:FreshMazeData(cb)
    GameUtils.Request(Interfaces.MazeEnte, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        if not jsonData then
            return
        end
        self.nextInfo = checkTable(jsonData.nextInfo)--下一步信息
        self.monsterCombat = checkNumber(jsonData.monsterCombat)--怪物战力（意义不明）
        self.currentInfo = checkTable(jsonData.currentInfo)--当前步信息
        --print("FreshMazeData-currentInfo-->>"..table.dump(self.currentInfo, nil, 3))
        self.currentPos = checkNumber(jsonData.currentPos)--当前选择的位置
        self.escapeTimes = checkNumber(jsonData.escapeTimes)                 --已逃跑次数
        self.escapeMaxTimes = checkNumber(jsonData.escapeMaxTimes)                 --最大逃跑次数
        self.monsterList = checkTable(jsonData.monsterList)--怪物列表
        self.relicOptions = checkTable(jsonData.relicOptions)
        self.coin = checkNumber(jsonData.coin)      --剩余货币
        self.cardsInfo = checkTable(jsonData.cardsInfo)--卡牌数据
        self.backpack = checkTable(jsonData.backpack)--背包数据
        self.currentFloor = checkNumber(jsonData.currentFloor)--当前层数
        self.remainTime = checkNumber(jsonData.remainTime)   --剩余时间
        self.isPassed = checkNumber(jsonData.passed) == 1 and true or false
        self.isJoined = checkNumber(jsonData.joined) == 1 and true or false
        self.mazeDifficultyId = jsonData.mazeDifficultyId
        printInfo("data======>>"..table.dump(jsonData, nil, 3))
        --请求数据  创建迷宫背包和队伍实体
        local worldMgr = ECSWorldMgr:GetInstance()
        ---@type ECSWorld
        local world = worldMgr:GetWorld(Constants.GameWorld)
        local entity
        ---@type ECSEntity
        if not world:GetEntity(tostring(Constants.MazeTeamEntityId)) then
            entity = world:CreateEntity(tostring(Constants.MazeTeamEntityId), Constants.MazeTeamEntityId)
            entity:AddComp(ECSComponentType.Constants.MazeTeamComponent)
        end
        if not world:GetEntity(tostring(Constants.MazeBagEntityId)) then
            entity = world:CreateEntity(tostring(Constants.MazeBagEntityId), Constants.MazeBagEntityId)
            entity:AddComp(ECSComponentType.Constants.MazeBagComponent)
        end
        --在迷宫入口 重新导入一下背包和队伍实体
        mazeBagComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MazeBagComponent, Constants.MazeBagEntityId)
        mazeTeamComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MazeTeamComponent, Constants.MazeTeamEntityId)

        --MazeMapMgr:GetInstance():InitMap(jsonData.map)  --地图

        --self.themeId = checkString(jsonData.themeId)  --主题id+
        --self.mapId = checkString(jsonData.mapId)   --地图id
        --self.coin = checkNumber(jsonData.coin)      --剩余货币
        --self.relicOptions = jsonData.relicOptions     --待领取的圣物buff
        --self.foot = jsonData.foot           --历史记录  直接循环遍历最高 所以就不排序了
        --self.escapeMaxTimes = checkNumber(jsonData.escapeMaxTimes)                 --最大逃跑次数
        --self.escapeTimes = checkNumber(jsonData.escapeTimes)                 --已逃跑次数
        --self.isFirst = checkNumber(jsonData.isFirst)   --是否进入过
        --self.isDrawReward = checkNumber(jsonData.isDrawBox) == 1 and true or false



        --如果是第一次进入重置下队伍
        if not self.isJoined then
            local teamComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.TeamComponent)
            teamComponent:ClearTeamBySystemId(Constants.SystemToggleIds.Id8)
        end

        local monsterList = jsonData.monsterList   --怪物列表
        if monsterList then
            self.monstInfos = {}
            for k, v in pairs(monsterList) do
                self.monstInfos[checkNumber(v.monsterId)] = v
            end
        end
        self.monsterCombat = checkNumber(jsonData.monsterCombat)   --怪物战力

        --local point = self:InitFootInfo()
        --MazeMapMgr:GetInstance():SetCurPoint(point)    --设置当前点

        --初始化背包
        mazeBagComp:InitBag(jsonData.goods, jsonData.relics, jsonData.curses)  --背包， 圣物， 诅咒

        --初始化角色编队
        mazeTeamComp:InitRoles(jsonData.cardsInfo)
        if cb then
            cb(self.remainTime)
        end
    end)
end



