--领取奖励
function MazeMgr:DrawRewardReq()
    GameUtils.Request(Interfaces.MazeDrawQuestBox, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        self.isDrawReward = true
        local responseData = checkTable(response.data)
        local t = responseData.rewards
        if t then
            GoodsUtils.DrawRewards(t)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = t, cb = {
                GameUtils.SecondConfirm(localize("恭喜通关"), function(  )
