                        { id = Constants.UITypeIds.UIHomeView },{}
                    }, Constants.LoadingType.MainHome, true)
                end, function(  )
                    GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, {
                        { id = Constants.UITypeIds.UIHomeView },{}
                    }, Constants.LoadingType.MainHome, true)
                end)
            }} })   
        end
    end)
end

