--选择剧情
function MazeMgr:MazeMoveToEvent(optionId, cb)
    if isNull(optionId) then
        return
    end
    GameUtils.Request(Interfaces.MazeMoveToEvent, {optionId = optionId}, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local jsonData = response.data
            local rewardShowList = {}
            local curses = jsonData.curses
            if curses then
                for k, v in pairs(curses) do
                    --mazeBagComp:Additem(k, Constants.IDType.Curses)
                    table.insert(rewardShowList, {
                        goodsId = k,
                        num = 1,
                        idAreaType = Constants.IDArea.Maze,
                    })
                end
            end
            local relics = jsonData.relics
            if relics then
                for k, v in pairs(relics) do
                    --mazeBagComp:Additem(k, Constants.IDType.Relics)
                    table.insert(rewardShowList, {
                        goodsId = k,
                        num = 1,
                        idAreaType = Constants.IDArea.Maze,
                    })
                end
            end
            local mazeGoods = jsonData.mazeGoods
            if mazeGoods then
                for k, v in pairs(mazeGoods) do
                    local data = {
                        goodsId = k,
                        num = v,
                        idAreaType = Constants.IDArea.Maze,
                    }
                    table.insert(rewardShowList, data)
                    --mazeBagComp:Additem(data, Constants.IDType.MazeItem)
                end
            end

            --只会出现迷宫币
            local rewards = jsonData.rewards
            if rewards then
                for k, v in pairs(rewards) do
                    --如果是金币
                    if checkNumber(v.goodsId) == Constants.Currency.MazeCurrency then
                        self:SetMazeCurrencyNum(self:GetMazeCurrencyNum() + checkNumber(v.num))
                    else
                        --mazeBagComp:Additem(v, Constants.IDType.MazeItem)
                    end
                    table.insert(rewardShowList, v)
                end
            end
            Events.Broadcast(Constants.EventNames.PatrolEventClose)
            --UIModule.OpenDialog(
            --        {
            --            id = Constants.UITypeIds.UICommonRewardPop,
            --            parameters = { rewards = rewardShowList }
            --        }
            --)
            self:FreshMazeData(function ()
                Events.Broadcast(Constants.EventNames.PatrolEventMain)
            end)
            if cb then
                cb(rewardShowList)
            end
        end
    end)
end

