---MazeUseGoods   使用迷宫道具
---@param mazeGoodsId integer @ 迷宫道具id
---@param targetType integer @ 目标类型，1卡牌2助手
---@param targetId integer @ 目标id
function MazeMgr:MazeUseGoods(mazeGoodsId, targetType, targetId)
    if targetType then
        targetType = checkNumber(targetType) == Constants.MazeRole.AssistRole and checkNumber(targetType) or Constants.MazeRole.CardHase
    end
    GameUtils.Request(Interfaces.MazeUseGoods, {mazeGoodsId = mazeGoodsId, targetType = targetType, targetId = targetId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        mazeBagComp:Delitem(mazeGoodsId, 1)
        
        local jsonData = response.data
        --更新诅咒
        mazeBagComp:DelCurses(jsonData.disperseCurses)

        --更新角色信息
        mazeTeamComp:UndateRoleHp(jsonData.cureRoles)
        mazeTeamComp:RebornRole(jsonData.rebornRoles)
        mazeTeamComp:UpdateRoleSp(jsonData.cureSpRoles)
        --if targetType then
            Events.Broadcast(Constants.EventNames.PatrolEventUseItem)
        --end
    end)
end

