--激活当前点的事件
function MazeMgr:ActiveEvent()
    local point = MazeMapMgr:GetInstance():GetCurPoint()
    local switch = {
        [Constants.MazePointType.StartPoint] = function()
            Events.Broadcast(Constants.EventNames.MazeRefeshPreview)
        end,
        [Constants.MazePointType.OrdinaryBattle] = function()
            self:ActiveBattleEvnet()
        end,
        [Constants.MazePointType.CreamBattle] = function()
            self:ActiveBattleEvnet()      
        end,
        [Constants.MazePointType.BossBattle] = function()
            self:ActiveBattleEvnet()
        end,
        [Constants.MazePointType.MysteriousShop] = function()
            self:CloseMazeMainGameObject()
            self:ActiveShopEvnet()
        end,
        [Constants.MazePointType.CommonShop] = function()
            self:CloseMazeMainGameObject()
            self:ActiveShopEvnet()
        end,
        [Constants.MazePointType.Story] = function()
            self:CloseMazeMainGameObject()
            self:ActiveStoryEvnet()
        end,
        [Constants.MazePointType.JoinBattle] = function()
            self:CloseMazeMainGameObject()
            self:ActiveJoinBattleEvnet()
        end,
        [Constants.MazePointType.UnKnown] = function()
            
        end,
    }
    switch[point.type]()
end

