--[[
    @desc: 当前显示视图信息
    author:{author}
    time:2020-06-23 17:59:30
    @return:
]]
function MazeMgr:GetCurPreViewData()
    local point = MazeMapMgr:GetInstance():GetCurPoint()
    if not point then
        return
    end

    local t = {}
    --如果已经通关了当前关卡， 显示下一关的数据
    if self:IsPassCurPoint(point) then
        t = MazeMapMgr:GetInstance():GetNextPoints(point)
    else
        table.insert(t, point)
    end
    return t
end

---IsPassCurPoint  是否通关当前关卡   通过历史记录判断
---@param point MazeMapPointDojo
function MazeMgr:IsPassCurPoint(point)
    --如果是空 设为当前点
    if not point then
        point = MazeMapMgr:GetInstance():GetCurPoint()
    end
    if not point then
        return false
    end

    --起点直接返回true
    if checkNumber(point.type) == Constants.MazePointType.StartPoint then
        return true
    end

    if point.passType == Constants.MazePointPassType.NotActive or 
        point.passType == Constants.MazePointPassType.GetTo then
            return false
    end
    return true
end

--是否激活了boss关口
function MazeMgr:IsActiveBossPoint()
    local curPoint = MazeMapMgr:GetInstance():GetCurPoint()
    if not curPoint then
        return false
    end

    local bossPoint = MazeMapMgr:GetInstance():GetPointByType(Constants.MazePointType.BossBattle)
    if bossPoint then
        if ((bossPoint.line - curPoint.line) <= 1) and self:IsPassCurPoint(curPoint) then
            return true
        end
    end
    return false
end

--是否通关了boss关口
function MazeMgr:IsPassBossPoint()
    local bossPoint = MazeMapMgr:GetInstance():GetPointByType(Constants.MazePointType.BossBattle)
    if bossPoint then
        if self:IsPassCurPoint(bossPoint) then
            return true
        end
    end
    return false
end

---GetFootInfo  获取某点再足迹中的信息
---@param point MazeMapPointDojo
function MazeMgr:GetFootInfo(point)
    for k, v in pairs(self.foot) do
        if checkNumber(k) == checkNumber(point.line) then
            if checkNumber(v.position) == checkNumber(point.row) then
                return v
            end
        end
    end
    return nil
end

--获取迷宫关卡描述
function MazeMgr:GetCurPointAndName()
    local curPointStr, name
    local point = MazeMapMgr:GetInstance():GetCurPoint()
    if point then
        if point.type == Constants.MazePointType.BossBattle then
            --curPointStr = MazeMapMgr:GetInstance():GetMaxLineNum().."/"..MazeMapMgr:GetInstance():GetMaxLineNum()
            curPointStr = nil
        else
            curPointStr = (checkNumber(point.line) - 1 >= 10 and checkNumber(point.line) - 1 or "0"..point.line - 1).."/"..MazeMapMgr:GetInstance():GetMaxLineNum()
        end
        name = CfUtils.GetCfData(AutoIds.IdSetting351, point.type, Constants.Tab_MazeEventType.name)     
    else
        curPointStr = ""
        name = ""   
    end
    return curPointStr, name
end

