function MazeMgr:Clear()
    if self.moveCor then
        self.isMoving = false
        cs_coroutine.stop(self.moveCor)
        self.moveCor = nil
    end
    MazeMapMgr:GetInstance():Clear()
    MazePlayerMgr:GetInstance():Clear()

    --清除实体
    ---@type ECSWorld
    local worldMgr = ECSWorldMgr:GetInstance()
    ---@type ECSWorld
    local world = worldMgr:GetWorld(Constants.GameWorld)
    world:DestroyEntityImmediately(Constants.MazeBagEntityId)
    world:DestroyEntityImmediately(Constants.MazeTeamEntityId)
    
    self:__delete()
    self.Destroy(self)   --这个好像没用
end

return MazeMgr
